"use strict";
import styled from "styled-components";
import { Flex, SpinningLoader, Text } from "ui/src";
export default function LockCreateCancelButton({
  onCreateClick,
  onCancelClick,
  isDisabled = false,
  isProcessing = false,
  buttonText = "Create lock",
  showCancel = true
}) {
  const Button = styled.button`
    all: unset;
    padding: 16px 10px;
    border: 1px solid ${({ theme }) => theme.surface3};
    background-color: ${({ $isDisabled, theme, $lock }) => $isDisabled ? theme.surface2 : $lock ? theme.surface2Hovered : theme.accent1};
    color: ${({ $isDisabled, theme, $lock }) => $isDisabled ? theme.accent1 : $lock ? theme.accent1 : theme.surface1};
    border-radius: 12px;
    cursor: ${({ $isDisabled }) => $isDisabled ? "not-allowed" : "pointer"};
    display: flex;
    justify-content: center;
    align-items: center;
    flex: 1;
    transition: all 0.2s ease;
    opacity: ${({ $isDisabled }) => $isDisabled ? 0.6 : 1};
    &:hover {
      opacity: ${({ $isDisabled }) => $isDisabled ? 0.6 : 0.7};
    }
  `;
  return <Flex mt={"$spacing24"} row gap={"$gap12"} alignItems="center">
      {showCancel && <Button $lock onClick={onCancelClick} $isDisabled={isProcessing}>
          <Text variant="buttonLabel3" color={"inherit"}>
            Cancel
          </Text>
        </Button>}

      <Button onClick={onCreateClick} $isDisabled={isDisabled || isProcessing}>
        <Flex row gap={"$gap8"} alignItems="center">
          {isProcessing && <SpinningLoader size={20} />}
          <Text variant="buttonLabel3" color={"inherit"}>
            {isProcessing ? "Processing..." : buttonText}
          </Text>
        </Flex>
      </Button>
    </Flex>;
}
