"use strict";
import AmountInput from "pages/Locks/common/AmoutInput";
import AvailableAmoutAndBalancePercentage from "pages/Locks/common/AvailableAmoutAndBalancePercentage";
import LockTimeAndVotingPower from "pages/Locks/common/LockTimeAndVotingPower";
import { Flex, Text, useSporeColors } from "ui/src";
import { useCreateLockFlow } from "../hooks/useCreateLockFlow";
import LockCreateCancelButton from "./LockCreateCancelButton";
import RangeInput from "./Range";
export default function CreateLock() {
  const colors = useSporeColors();
  const {
    formState,
    updateFormState,
    flowState,
    executeFlow,
    votingPowerPreview,
    userABXBalance,
    needsApproval,
    isProcessing,
    isConnected,
    resetFlow
  } = useCreateLockFlow();
  const handleAmountChange = (amount) => {
    updateFormState({ amount });
  };
  const handleDurationChange = (lockDurationInDays) => {
    updateFormState({ lockDurationInDays });
  };
  const handlePercentageSelect = (percentage) => {
    const userBalanceNum = parseFloat(userABXBalance);
    if (userBalanceNum > 0) {
      const calculatedAmount = (userBalanceNum * percentage / 100).toString();
      handleAmountChange(calculatedAmount);
    }
  };
  const renderFlowContent = () => {
    switch (flowState.step) {
      case "approve":
        return <Flex centered py="$spacing20">
            <Text variant="body2" color="$neutral2" textAlign="center">
              Approving ABX tokens for locking...
            </Text>
          </Flex>;
      case "create":
        return <Flex centered py="$spacing20">
            <Text variant="body2" color="$neutral2" textAlign="center">
              Creating your veABX lock...
            </Text>
          </Flex>;
      case "confirming":
        return <Flex centered py="$spacing20" gap="$spacing8">
            <Text variant="body2" color="$neutral2" textAlign="center">
              Waiting for transaction confirmation...
            </Text>
            {flowState.transactionHash && <Text variant="body4" color="$neutral3" textAlign="center">
                Tx: {flowState.transactionHash.slice(0, 10)}...
              </Text>}
          </Flex>;
      case "success":
        return <Flex centered py="$spacing20" gap="$spacing12">
            <Text variant="body2" color="$statusSuccess" textAlign="center">
              Lock created successfully! 🎉
            </Text>
            <Text variant="body3" color="$neutral2" textAlign="center">
              Your veABX tokens will appear in your locks list shortly.
            </Text>
            {flowState.transactionHash && <Text variant="body4" color="$neutral3" textAlign="center">
                Tx: {flowState.transactionHash.slice(0, 10)}...
              </Text>}
          </Flex>;
      case "error":
        return <Flex centered py="$spacing20" gap="$spacing8">
            <Text variant="body2" color="$statusCritical" textAlign="center">
              Transaction failed
            </Text>
            <Text variant="body3" color="$neutral3" textAlign="center">
              {flowState.error}
            </Text>
          </Flex>;
      default:
        return <>
            <AvailableAmoutAndBalancePercentage
          title="Amount"
          onPercentageSelect={handlePercentageSelect}
        />
            <AmountInput
          value={formState.amount}
          onValueChange={handleAmountChange}
          error={formState.errors.amount}
          userBalance={userABXBalance}
        />

            <RangeInput
          value={formState.lockDurationInDays}
          onValueChange={handleDurationChange}
        />
            {formState.errors.duration && <Text variant="body3" color="$statusCritical" mt="$spacing8" textAlign="center">
                {formState.errors.duration}
              </Text>}

            <Flex mt={"$gap24"}>
              <LockTimeAndVotingPower
          votingPower={votingPowerPreview}
          lockDuration={formState.lockDurationInDays}
        />
            </Flex>
          </>;
    }
  };
  return <Flex
    flexDirection="column"
    p={"$spacing16"}
    borderRadius={"$rounded12"}
    borderWidth={1}
    borderColor={"$surface3"}
    style={{
      background: `linear-gradient(180deg, ${colors.surface2.variable} 0%, transparent 100%)`
    }}
  >
      {renderFlowContent()}

      <LockCreateCancelButton
    onCreateClick={executeFlow}
    onCancelClick={resetFlow}
    isDisabled={!formState.isValid || !isConnected || isProcessing}
    isProcessing={isProcessing}
    buttonText={flowState.step === "success" ? "Create Another Lock" : needsApproval ? "Approve & Create Lock" : "Create Lock"}
    showCancel={flowState.step === "input"}
  />
    </Flex>;
}
